class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now } = {}) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFunc = now;

    // Başlangıç durumu
    this.lastRefillTime = this.nowFunc();
    this.currentTokens = capacity;
  }

  _refill() {
    const currentTime = this.nowFunc();
    const deltaTimeSeconds = (currentTime - this.lastRefillTime) / 1000;

    // Saat geri giderse veya aynı kalırsa işlem yapma
    if (deltaTimeSeconds > 0) {
      const tokensToAdd = deltaTimeSeconds * this.refillPerSecond;
      this.currentTokens = Math.min(this.capacity, this.currentTokens + tokensToAdd);
      this.lastRefillTime = currentTime;
    }
  }

  tryTake(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.currentTokens >= n) {
      this.currentTokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this.currentTokens;
  }

  msUntil(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.currentTokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity;
    }

    const needed = n - this.currentTokens;
    const secondsNeeded = needed / this.refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function test() {
  console.log('Starting tests...');

  // 1. Basic functionality
  {
    let time = 1000;
    const now = () => time;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

    assert.strictEqual(bucket.available(), 10, 'Should start full');
    assert.strictEqual(bucket.tryTake(5), true, 'Should take 5 tokens');
    assert.strictEqual(bucket.available(), 5, 'Remaining should be 5');

    time += 1000; // 1 second passes, should refill 2 tokens
    assert.strictEqual(bucket.available(), 7, 'Should have refilled 2 tokens');

    time += 500; // 0.5 seconds passes, should refill 1 token
    assert.strictEqual(bucket.available(), 8, 'Should have refilled 1 token');

    console.log('✅ Basic functionality passed');
  }

  // 2. Capacity limit
  {
    let time = 1000;
    const now = () => time;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5, now });

    time += 10; // very small time
    assert.strictEqual(bucket.available(), 10, 'Should not exceed capacity');

    console.log('✅ Capacity limit passed');
  }

  // 3. Time going backwards
  {
    let time = 1000;
    const now = () => time;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

    bucket.tryTake(5); // current: 5
    time += 1000; // time is 2000, tokens = 5 + 2 = 7
    assert.strictEqual(bucket.available(), 7, 'Should refill normally');

    time -= 500; // time is 1500 (goes back!)
    assert.strictEqual(bucket.available(), 7, 'Should not refill or decrease when time goes backwards');

    console.log('✅ Time backwards handled');
  }

  // 4. msUntil
  {
    let time = 1000;
    const now = () => time;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

    assert.strictEqual(bucket.msUntil(5), 0, 'Should return 0 if tokens are available');

    bucket.tryTake(10); // current: 0
    // To get 5 tokens, we need 5 / 2 = 2.5 seconds = 2500 ms
    assert.strictEqual(bucket.msUntil(5), 2500, 'Should return 2500ms for 2.5s refill');

    const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now });
    bucket2.tryTake(5); // current: 5
    assert.strictEqual(bucket2.msUntil(6), Infinity, 'Should return Infinity if refillRate is 0 and tokens needed');

    const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now });
    bucket3.tryTake(10); // current: 0
    assert.strictEqual(bucket3.msUntil(11), Infinity, 'Should return Infinity if n > capacity');

    console.log('✅ msUntil passed');
  }

  // 5. Errors
  {
    assert.throws(() => new TokenBucket({ capacity: 0, refillPerSecond: 1 }), RangeError, 'Capacity must be > 0');
    assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: -1 }), RangeError, 'Refill must be non-negative');
    const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
    assert.throws(() => b.tryTake(-1), RangeError, 'n must be positive');
    assert.throws(() => b.msUntil(0), RangeError, 'n must be positive');
    console.log('✅ Error handling passed');
  }

  console.log('All tests passed successfully!');
}

try {
  test();
} catch (e) {
  console.error('❌ Test failed!');
  console.error(e);
  process.exit(1);
}

